const adrafinil = "/Applications/Adrafinil.app/Contents/Helpers/adrafinil"

// Hold only while a turn runs. One long-lived server hosts every chat, so
// Adrafinil never sees a process exit; the ttl is the backstop for a missed idle.
export const Adrafinil = async ({ $ }) => {
  const held = new Set<string>()
  const release = async (id: string) => {
    if (!held.delete(id)) return
    await $`${adrafinil} release ${id}`.quiet().nothrow()
  }
  return {
    event: async ({ event }) => {
      if (event.type === "session.deleted") return release(event.properties.info.id)
      if (event.type !== "session.status") return
      const id = event.properties.sessionID
      const status = event.properties.status.type
      if (status === "idle") return release(id)
      if (status !== "busy" || held.has(id)) return
      held.add(id)
      await $`${adrafinil} acquire ${id} --tool opencode --ttl 3600`.quiet().nothrow()
    },
  }
}
